mapper.select:
SELECT todo_id, user_no, title, content, schedule_date, status, file_url, file_name FROM todo WHERE user_no = #{user_no}
AND title LIKE '%' || #{keyword} || '%'
ORDER BY schedule_date ASC OFFSET #{offset} ROWS FETCH NEXT #{amount} ROWS ONLY

mapper.update:
UPDATE todo
SET title = #{title},
    content = #{content},
    schedule_date = #{schedule_date},
    status = #{status}
WHERE todo_id = #{todo_id}

UPDATE todo
SET file_url = #{file_url},
    file_name = #{file_name}
WHERE todo_id = #{todo_id}
